    as_root git -C "$APP_DIR" fetch --depth 1 origin "$REPO_REF"
    as_root git -C "$APP_DIR" checkout --force FETCH_HEAD
  elif [[ -e $APP_DIR ]]; then
    printf 'install.sh: APP_DIR exists and is not a git repo: %s\n' "$APP_DIR" >&2
    exit 1
