fi

BIN_PATTERN='bin/installr'
BIN_OVERRIDE=
case "${OS}_${ARCH}" in
  linux_amd64) BIN_OVERRIDE='' ;;
  linux_arm64) BIN_OVERRIDE='' ;;
  darwin_amd64) BIN_OVERRIDE='' ;;
  darwin_arm64) BIN_OVERRIDE='' ;;
  *)
    printf 'install.sh: no binary for %s-%s\n' "$OS" "$ARCH" >&2
    exit 1
    ;;
esac

