write_root "$APP_DIR/uninstall.sh" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail

HERE=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)
LOG=$HERE/install.log
