printf 'symlink: %s\n' "$BIN_DIR/$APP_NAME"
printf 'files: %s\n' "$FILES_SUMMARY"
case ${CONFIG_ACTION:-skipped} in
  copied) printf 'config: copied %s\n' "$CONFIG_DEST" ;;
  replaced) printf 'config: replaced %s\n' "$CONFIG_DEST" ;;
